#!/usr/bin/env python3
"""Reads a jarvis-problem issue, asks Gemini for a minimal code fix and applies it to the working tree.
Never pushes anything itself: the workflow builds the result and opens a pull request only if the build passes."""
import json, os, pathlib, re, sys, urllib.error, urllib.request

ROOT = pathlib.Path(".")
SRC = ROOT / "app" / "src" / "main"
ALLOWED_PREFIX = "app/src/main/"
MAX_CHARS = 220_000


def set_output(key, value):
    with open(os.environ["GITHUB_OUTPUT"], "a") as f:
        f.write(f"{key}={value}\n")


def ask_gemini(prompt, key):
    models = [os.environ.get("AUTOFIX_MODEL", "").strip(), "gemini-2.5-flash", "gemini-2.0-flash", "gemini-1.5-flash"]
    last = ""
    for m in [x for x in models if x]:
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{m}:generateContent?key={key}"
        body = json.dumps({
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {"responseMimeType": "application/json", "temperature": 0.2},
        }).encode()
        req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=180) as r:
                data = json.load(r)
            return json.loads(data["candidates"][0]["content"]["parts"][0]["text"])
        except urllib.error.HTTPError as e:
            last = f"{m}: HTTP {e.code}"
        except Exception as e:  # noqa: BLE001
            last = f"{m}: {type(e).__name__}"
    raise RuntimeError("all models failed: " + last)


def main():
    issue = pathlib.Path("issue.txt").read_text(encoding="utf-8")
    key = os.environ["GEMINI_API_KEY"]
    files = sorted(SRC.rglob("*.kt"))
    tokens = set(re.findall(r"[A-Za-z_][A-Za-z0-9_]{4,}", issue))
    scored = []
    for p in files:
        text = p.read_text(encoding="utf-8")
        score = sum(1 for t in tokens if t in text)
        scored.append((score, -len(text), p, text))
    scored.sort(key=lambda x: (x[0], x[1]), reverse=True)
    chosen, total = [], 0
    for score, _, p, text in scored:
        if total + len(text) > MAX_CHARS:
            continue
        if score == 0 and len(chosen) >= 2:
            break
        chosen.append((p, text))
        total += len(text)
        if len(chosen) >= 4:
            break

    listing = "\n\n".join(f"=== FILE: {p.as_posix()} ===\n{t}" for p, t in chosen)
    prompt = f"""You maintain an Android app written in Kotlin (a voice assistant that controls the phone through an AccessibilityService).
The app reported these problems from a real phone. Find the most likely code cause and propose the SMALLEST safe fix.

PROBLEM REPORT:
{issue[:6000]}

SOURCE FILES:
{listing}

Reply with ONLY this JSON object:
{{"analysis":"short explanation in English","confidence":"low|medium|high","edits":[{{"path":"app/src/main/...","old":"exact existing text that occurs exactly once in that file","new":"replacement text"}}]}}

Rules:
- Edit only the files shown above. Keep every edit minimal; do not refactor or reformat.
- "old" must be copied exactly (whitespace included) and be unique in its file.
- Never touch signing, secrets, workflows, build files or permissions.
- If the cause is not in the code (missing permission, no internet, API quota, user setting, third-party app change you cannot verify), return "edits": [] and explain what the user should do.
- Do not invent APIs. Prefer defensive handling (null checks, retries, fallbacks, clearer error messages) over speculative rewrites."""

    result = ask_gemini(prompt, key)
    analysis = str(result.get("analysis", ""))[:3000]
    confidence = str(result.get("confidence", "low"))
    applied = []
    for e in result.get("edits", []) or []:
        path = str(e.get("path", "")).lstrip("./")
        old, new = e.get("old", ""), e.get("new", "")
        if not path.startswith(ALLOWED_PREFIX) or ".." in path or not path.endswith(".kt"):
            continue
        fp = ROOT / path
        if not fp.exists() or not old or old == new:
            continue
        text = fp.read_text(encoding="utf-8")
        if text.count(old) != 1:
            continue
        fp.write_text(text.replace(old, new), encoding="utf-8")
        applied.append(path)

    pathlib.Path("autofix_analysis.md").write_text(
        f"### Automatic analysis (confidence: {confidence})\n\n{analysis}\n\n"
        + ("**Files changed:** " + ", ".join(sorted(set(applied))) if applied else "**No code change proposed.**")
        + "\n\n_Generated by the autofix workflow. Review before merging; nothing is merged automatically._\n",
        encoding="utf-8",
    )
    set_output("edited", "true" if applied else "false")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:  # noqa: BLE001
        pathlib.Path("autofix_analysis.md").write_text(f"Autofix could not run: {exc}\n", encoding="utf-8")
        set_output("edited", "false")
